export const n = 8;
export const num = "08";
export const title = "Undo — restore، reset، revert و reflog";
export const label = "فصل ۸ · Undo در Git";
export const part = 0;
export const html = "<p class=\"lead\">Undo در Git یک فرمان نیست — چهار کار مختلف است. قبل از اجرا باید بدانی فایل روی دیسک را برمی‌گردانی، پیش‌نویس را خالی می‌کنی، اشاره‌گر شاخه را حرکت می‌دهی، یا یک کامیت جدیدِ خنثی می‌سازی.</p>\n  <h2><span class=\"hx\"><span class=\"hx-t\">🎯 اهداف یادگیری</span></span></h2>\n<ul>\n<li>نقشهٔ Undo را از حفظ بکشی</li>\n<li><code>restore</code> را جایگزین checkout فایل کنی</li>\n<li>سه حالت reset را از هم جدا کنی</li>\n<li class=\"keep-next\">با <code>reflog</code> کامیت «گمشده» را زنده کنی</li>\n</ul>\n<div class=\"diagram\">\n<img src=\"/book/figures/undo-map.svg\" alt=\"نقشه Undo\"/>\n<p class=\"figcap\">شکل ۷ — قانون طلایی: تاریخچهٔ عمومی را فقط با revert لمس کن.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">🧹 Working Tree و Index</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">بازگردانی فایل — مدرن</span></div><pre>git<span style=\"color: #F8F8F2\"> </span>restore<span style=\"color: #F8F8F2\"> </span>src/auth.ts<span style=\"color: #F8F8F2\">                 </span><span style=\"color: #959077\"># Working ← Index</span>\ngit<span style=\"color: #F8F8F2\"> </span>restore<span style=\"color: #F8F8F2\"> </span>--staged<span style=\"color: #F8F8F2\"> </span>src/auth.ts<span style=\"color: #F8F8F2\">        </span><span style=\"color: #959077\"># Index ← HEAD</span>\ngit<span style=\"color: #F8F8F2\"> </span>restore<span style=\"color: #F8F8F2\"> </span>--source<span style=\"color: #FF4689\">=</span>HEAD<span style=\"color: #F8F8F2\"> </span>--staged<span style=\"color: #F8F8F2\"> </span>--worktree<span style=\"color: #F8F8F2\"> </span>src/auth.ts\n<span style=\"color: #959077\"># هر دو درخت فایل = HEAD  (معادل checkout -- file)</span>\ngit<span style=\"color: #F8F8F2\"> </span>restore<span style=\"color: #F8F8F2\"> </span>--source<span style=\"color: #FF4689\">=</span>main~3<span style=\"color: #F8F8F2\"> </span>README.md<span style=\"color: #F8F8F2\">   </span><span style=\"color: #959077\"># نسخهٔ قدیمی را بیاور</span>\n</pre></div>\n<div class=\"cols\">\n<div class=\"col\"><div class=\"col-title\">🖥️ VS Code Git</div>\n<ul>\n<li>Changes → آیکون ↩ <strong>Discard Changes</strong> = <code>restore</code></li>\n<li>Staged → <strong>-</strong> <strong>Unstage</strong> = <code>restore --staged</code></li>\n<li>منوی <code>...</code> → <em>Commit → Undo Last Commit</em> = <code>reset --soft</code></li>\n<li>Timeline فایل را بعد از Discard هم گاهی نجات می‌دهد</li>\n<li><em>Discard All</em> خطرناک است</li>\n</ul>\n</div>\n<div class=\"col\"><div class=\"col-title\">⌨️ Terminal</div>\n<p><code>git restore file</code>\n<code>git restore --staged file</code>\n<code>git reset --soft HEAD~1</code>\n<code>git reflog</code> برای نجات</p>\n</div>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">🧱 سه چهرهٔ reset</span></span></h2>\n<p class=\"keep-next\">فرض: <code>A--B--C (HEAD)</code> و می‌خواهی به <code>B</code> برگردی.</p>\n<div class=\"tbl-wrap\"><table><thead>\n<tr>\n<th>فرمان</th>\n<th>HEAD</th>\n<th>Index</th>\n<th>Working</th>\n<th>استفاده</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>--soft B</code></td>\n<td>B</td>\n<td>محتوای C</td>\n<td>محتوای C</td>\n<td>کامیت را بشکن، تغییرات بماند staged</td>\n</tr>\n<tr>\n<td><code>--mixed B</code> (پیش‌فرض)</td>\n<td>B</td>\n<td>B</td>\n<td>محتوای C</td>\n<td>کامیت را بشکن، تغییرات unstaged</td>\n</tr>\n<tr>\n<td><code>--hard B</code></td>\n<td>B</td>\n<td>B</td>\n<td>B</td>\n<td>همه‌چیز برود</td>\n</tr>\n</tbody>\n</table></div><div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">مثال‌های امن</span></div><pre>git<span style=\"color: #F8F8F2\"> </span>reset<span style=\"color: #F8F8F2\"> </span>--soft<span style=\"color: #F8F8F2\"> </span>HEAD~1<span style=\"color: #F8F8F2\">        </span><span style=\"color: #959077\"># پیام/فایل‌ها را دوباره بچین</span>\ngit<span style=\"color: #F8F8F2\"> </span>reset<span style=\"color: #F8F8F2\"> </span>HEAD~1<span style=\"color: #F8F8F2\">               </span><span style=\"color: #959077\"># همان، اما unstaged</span>\n<span style=\"color: #959077\"># git reset --hard HEAD~1     # فقط اگر مطمئنی</span>\n</pre></div>\n<p>در VS Code منوی <code>...</code> در Source Control: <em>Commit → Undo Last Commit</em> معمولاً <code>--soft</code>.</p>\n<div class=\"callout callout-danger\"><div class=\"callout-title\">هرگز reset --hard روی main مشترک</div>\n<p>اگر push شده، تاریخچهٔ دیگران را تکه‌پاره می‌کنی. به‌جایش <code>git revert</code>.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">↩️ revert — Undo عمومی</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">کامیت معکوس بساز</span></div><pre>git<span style=\"color: #F8F8F2\"> </span>revert<span style=\"color: #F8F8F2\"> </span>HEAD<span style=\"color: #F8F8F2\">                </span><span style=\"color: #959077\"># آخرین را خنثی کن</span>\ngit<span style=\"color: #F8F8F2\"> </span>revert<span style=\"color: #F8F8F2\"> </span>-m<span style=\"color: #F8F8F2\"> </span><span style=\"color: #AE81FF\">1</span><span style=\"color: #F8F8F2\"> </span>&lt;merge-sha&gt;<span style=\"color: #F8F8F2\">    </span><span style=\"color: #959077\"># خنثی‌کردن merge (والد ۱ = شاخهٔ هدف)</span>\n</pre></div>\n<p>Revert یک <strong>کامیت جدید</strong> می‌سازد که تغییرات را برعکس اعمال می‌کند. تاریخچه دروغ نمی‌گوید.</p>\n<p>در GitHub: روی PR دگمهٔ <em>Revert</em> همین کار را تمیزتر انجام می‌دهد.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">🛟 reflog — ماشین زمان اشاره‌گرها</span></span></h2>\n<p class=\"keep-next\">هر حرکت HEAD در reflog ثبت می‌شود (معمولاً ۹۰ روز).</p>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">زنده کردن کامیت گمشده</span></div><pre>git<span style=\"color: #F8F8F2\"> </span>reflog\n<span style=\"color: #959077\"># e3a1... HEAD@{0}: reset: moving to HEAD~1</span>\n<span style=\"color: #959077\"># 9f3a... HEAD@{1}: commit: feat(auth): ...</span>\n\ngit<span style=\"color: #F8F8F2\"> </span>switch<span style=\"color: #F8F8F2\"> </span>-c<span style=\"color: #F8F8F2\"> </span>rescue<span style=\"color: #F8F8F2\"> </span>HEAD@<span style=\"color: #FF4689\">{</span><span style=\"color: #AE81FF\">1</span><span style=\"color: #FF4689\">}</span>\n<span style=\"color: #959077\"># یا</span>\ngit<span style=\"color: #F8F8F2\"> </span>reset<span style=\"color: #F8F8F2\"> </span>--hard<span style=\"color: #F8F8F2\"> </span>9f3a1c\n</pre></div>\n<div class=\"callout callout-note\"><div class=\"callout-title\">چه چیزی را reflog نجات نمی‌دهد؟</div>\n<p>فایلی که <strong>هرگز add/commit</strong> نشده و Discard شده. Git آن را ندیده. از Local History خود VS Code (<code>Timeline</code>) کمک بگیر.</p>\n</div>\n<p>در VS Code: Timeline گاهی نسخه‌های محلی ذخیره می‌کند حتی بدون Git — آخرین تور ایمنی برای Untracked.</p>\n<div class=\"callout callout-interview\"><div class=\"callout-title\">سؤالات مصاحبه (با پاسخ)</div>\n<p><strong>Junior — تفاوت restore و reset؟</strong> restore فایل‌محور است؛ reset اشاره‌گر شاخه را حرکت می‌دهد.</p>\n<p><strong>Mid — soft در برابر mixed؟</strong> هر دو HEAD را حرکت می‌دهند؛ soft ایندکس را نگه می‌دارد.</p>\n<p><strong>Senior — revert یک merge چرا <code>-m 1</code> می‌خواهد؟</strong> چون merge دو والد دارد. باید بگویی «خط اصلی کدام است» تا diff معکوس معنا داشته باشد.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">✅ چک‌لیست فهم</span></span></h2>\n<div class=\"keep-block\"><div class=\"checklist\">\n<ul>\n<li>نقشهٔ Undo را بلدی</li>\n<li><code>restore</code> را به‌جای checkout فایل می‌زنی</li>\n<li><code>--hard</code> را برای کار عمومی ممنوع می‌دانی</li>\n<li>یک‌بار با reflog نجات داده‌ای</li>\n</ul>\n</div><p><strong>فصل بعد:</strong> gitignore، attributes و LFS.</p></div>";
export default { n, num, title, label, part, html };
